import pytest
from parse_kv import parse_kv


def test_empty_string():
    """An empty string should yield an empty dict."""
    assert parse_kv("") == {}


def test_single_pair():
    """Test parsing a single key-value pair."""
    assert parse_kv("key1=value1") == {"key1": "value1"}


def test_multiple_pairs():
    """Test parsing multiple key-value pairs."""
    assert parse_kv("key1=value1; key2=value2") == {"key1": "value1", "key2": "value2"}


def test_whitespace_trimming():
    """Keys and values should be whitespace-trimmed."""
    assert parse_kv("  key1  =  value1  ;  key2 = value2  ") == {"key1": "value1", "key2": "value2"}


def test_escaped_semicolon():
    """A backslash-escaped semicolon should be treated as a literal semicolon."""
    result = parse_kv("key1=val\\;ue; key2=value2")
    assert result == {"key1": "val;ue", "key2": "value2"}


def test_escaped_semicolon_in_middle():
    """Escaped semicolons in the middle of a value."""
    assert parse_kv("key=value\\;with\\;semicolons") == {"key": "value;with;semicolons"}


def test_multiple_escaped_semicolons():
    """Multiple escaped semicolons in a value."""
    assert parse_kv("a=1\\;;2\\;;3") == {"a": "1;;2;;3"}


def test_value_with_equals():
    """Values can contain equals signs."""
    assert parse_kv("key=value=with=equals") == {"key": "value=with=equals"}


def test_empty_value():
    """Values can be empty."""
    assert parse_kv("key=") == {"key": ""}


def test_key_with_whitespace():
    """Keys should be trimmed."""
    assert parse_kv(" key = value ") == {"key": "value"}


def test_multiple_pairs_with_escaped_semicolon():
    """Multiple pairs with escaped semicolons."""
    result = parse_kv("name=John\\;Doe; age=30; city=New York")
    assert result == {"name": "John;Doe", "age": "30", "city": "New York"}


def test_triple_backslash_semicolon():
    """\\; should become \; (backslash followed by semicolon)."""
    result = parse_kv("key=\\\\;")
    assert result == {"key": "\\;"}


def test_empty_value_with_whitespace():
    """Empty value with whitespace."""
    assert parse_kv("key=   ") == {"key": ""}


def test_key_without_value():
    """Key without equals sign is ignored."""
    assert parse_kv("key1=value1; noequals; key2=value2") == {"key1": "value1", "key2": "value2"}


def test_only_whitespace_pairs():
    """Only whitespace pairs should be ignored."""
    assert parse_kv("   ;  ;   ") == {}


def test_complex_case():
    """Complex case with multiple features."""
    result = parse_kv("  a = b\\;c ; d=e\\;f\\;g ;  h = i  ")
    assert result == {"a": "b;c", "d": "e;f;g", "h": "i"}


if __name__ == "__main__":
    pytest.main([__file__, "-v"])

